    name = name.lower()
    pos = [p for p in pats if not p.startswith("!")]
    neg = [p[1:] for p in pats if p.startswith("!")]
    if any(fnmatch.fnmatchcase(name, p.lower()) for p in neg):
        return False
    return any(fnmatch.fnmatchcase(name, p.lower()) for p in pos)


